import 'dart:io';
import 'dart:math' as math;
import 'dart:typed_data';

import '../guardrails.dart';

import 'package:path/path.dart' as p;
import 'package:path_provider/path_provider.dart';
import 'package:record/record.dart';

/// Processes only the 16 kHz mono PCM WAV generated by the recorder.
Future<void> normalizeRecordedWav(File file) async {
  if (await file.length() > 12 * 1024 * 1024) {
    throw const DictationException('audio_too_large', 'Recording is too long.');
  }
  final bytes = await file.readAsBytes();
  final data = ByteData.sublistView(bytes);
  bool tag(int at, String text) =>
      at + text.length <= bytes.length &&
      List.generate(text.length, (i) => bytes[at + i]).join(',') ==
          text.codeUnits.join(',');
  if (bytes.length < 44 || !tag(0, 'RIFF') || !tag(8, 'WAVE')) {
    throw const DictationException(
      'audio_format',
      'The recording has an unsupported audio format.',
    );
  }
  var pos = 12;
  int? sampleOffset;
  int? sampleLength;
  var formatValid = false;
  while (pos + 8 <= bytes.length) {
    final size = data.getUint32(pos + 4, Endian.little);
    final start = pos + 8;
    if (size > bytes.length - start) {
      throw const DictationException(
        'audio_format',
        'The recording is damaged.',
      );
    }
    if (tag(pos, 'fmt ') && size >= 16) {
      formatValid =
          data.getUint16(start, Endian.little) == 1 &&
          data.getUint16(start + 2, Endian.little) == 1 &&
          data.getUint32(start + 4, Endian.little) == 16000 &&
          data.getUint16(start + 14, Endian.little) == 16;
    } else if (tag(pos, 'data')) {
      sampleOffset = start;
      sampleLength = size;
    }
    pos = start + size + (size & 1);
  }
  if (!formatValid ||
      sampleOffset == null ||
      sampleLength == null ||
      sampleLength.isOdd) {
    throw const DictationException(
      'audio_format',
      'The recording has an unsupported audio format.',
    );
  }
  final samples = sampleLength ~/ 2;
  var first = samples;
  var last = -1;
  var peak = 0;
  for (var i = 0; i < samples; i++) {
    final value = data.getInt16(sampleOffset + i * 2, Endian.little).abs();
    peak = math.max(peak, value);
    if (value >= 300) {
      first = math.min(first, i);
      last = i;
    }
  }
  if (last < 0) {
    throw const DictationException(
      'audio_silent',
      'No speech detected. Check your microphone.',
    );
  }
  // shortcut: threshold detects quiet signal rather than speech, upgrade to VAD for noise discrimination.
  first = math.max(0, first - 1600);
  last = math.min(samples - 1, last + 1600);
  final outSize = (last - first + 1) * 2;
  final output = Uint8List(44 + outSize);
  final out = ByteData.sublistView(output);
  void writeTag(int offset, String value) =>
      output.setRange(offset, offset + value.length, value.codeUnits);
  writeTag(0, 'RIFF');
  out.setUint32(4, output.length - 8, Endian.little);
  writeTag(8, 'WAVE');
  writeTag(12, 'fmt ');
  out.setUint32(16, 16, Endian.little);
  out.setUint16(20, 1, Endian.little);
  out.setUint16(22, 1, Endian.little);
  out.setUint32(24, 16000, Endian.little);
  out.setUint32(28, 32000, Endian.little);
  out.setUint16(32, 2, Endian.little);
  out.setUint16(34, 16, Endian.little);
  writeTag(36, 'data');
  out.setUint32(40, outSize, Endian.little);
  final gain = math.min(4.0, 31128 / peak);
  for (var i = first; i <= last; i++) {
    final sample = data.getInt16(sampleOffset + i * 2, Endian.little);
    out.setInt16(
      44 + (i - first) * 2,
      (sample * gain).round().clamp(-32768, 32767),
      Endian.little,
    );
  }
  await file.writeAsBytes(output, flush: true);
}

class RecordedAudioResult {
  const RecordedAudioResult({required this.file, required this.durationMs});
  final File file;
  final int durationMs;
  int get durationSec => (durationMs / 1000).ceil();
}

class AudioService {
  final AudioRecorder _recorder = AudioRecorder();
  final Stopwatch _clock = Stopwatch();
  String? _path;

  Future<List<InputDevice>> listDevices() => _recorder.listInputDevices();
  Future<Amplitude> amplitude() => _recorder.getAmplitude();

  Future<void> start({String? deviceId}) async {
    if (_path != null) throw StateError('A recording is already active.');
    if (!await _recorder.hasPermission()) {
      throw Exception('Microphone permission denied.');
    }
    InputDevice? device;
    if (deviceId != null && deviceId.isNotEmpty) {
      final devices = await listDevices();
      device = devices.where((item) => item.id == deviceId).firstOrNull;
      if (device == null) {
        throw Exception('The selected microphone is unavailable.');
      }
    }
    final dir = await getTemporaryDirectory();
    final file = File(
      p.join(
        dir.path,
        'dictation_${DateTime.now().microsecondsSinceEpoch}.wav',
      ),
    );
    _path = file.path;
    try {
      await _recorder.start(
        RecordConfig(
          encoder: AudioEncoder.wav,
          sampleRate: 16000,
          numChannels: 1,
          device: device,
        ),
        path: file.path,
      );
      _clock
        ..reset()
        ..start();
    } catch (_) {
      _path = null;
      if (await file.exists()) await file.delete();
      rethrow;
    }
  }

  Future<RecordedAudioResult?> stop() async {
    final originalPath = _path;
    if (originalPath == null) return null;
    _clock.stop();
    final duration = _clock.elapsedMilliseconds;
    try {
      final path = await _recorder.stop();
      if (path == null) {
        final file = File(originalPath);
        if (await file.exists()) await file.delete();
        return null;
      }
      final file = File(path);
      DictationGuardrails.validateAudio(file, duration);
      await normalizeRecordedWav(file);
      return RecordedAudioResult(file: file, durationMs: duration);
    } catch (_) {
      final file = File(originalPath);
      if (await file.exists()) await file.delete();
      rethrow;
    } finally {
      _path = null;
    }
  }

  Future<void> dispose() async {
    final path = _path;
    try {
      await _recorder.dispose();
    } finally {
      _path = null;
      if (path != null) {
        final file = File(path);
        if (await file.exists()) await file.delete();
      }
    }
  }
}
